design_text:
{
  "site_summary": "A partial shade balcony with dry soil conditions and no pets in the household.",
  "layout_strategy": "The planting is structured vertically with trailing succulents on the edge railing, upright structural shrubs and herbs at mid-height against the back wall, and low rosette succulents creating a dense ground-level edge.",
  "combination_logic": "The scheme combines architectural uprights with soft cascading textures and tight rosettes, offering a contrast of grey-green foliage, aromatic textures, and smooth succulent surfaces that maintain their appearance year-round with minimal seasonal change.",
  "zones": [
    {
      "zone_name": "Railing Edge",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "on the outer partial shade railing, receiving filtered morning light and good air circulation",
      "plants": [
        {
          "scientific_name": "Echeveria elegans",
          "common_name": "Hens and Chickens",
          "why": "Adapts well to low moisture and partial shade while producing neat rosettes.",
          "role_in_combination": "Provides a neat, sculptural edge detail and soft blue-green colour contrast against the metallic railing."
        }
      ],
      "maintenance": [
        "Water sparingly only when the soil is completely dry",
        "Remove any dead lower leaves annually in spring",
        "Repot every two years into fresh gritty succulent compost"
      ]
    },
    {
      "zone_name": "Back Wall Containers",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "against the rear balcony wall in partial shade, sheltered from strong winds",
      "plants": [
        {
          "scientific_name": "Aloysia triphylla",
          "common_name": "Lemon Verbena",
          "why": "Thrives in dry partial shade and provides height and a strong lemon fragrance.",
          "role_in_combination": "Acts as the vertical backdrop and focal height anchor, contrasting with the stiff foliage of the succulents."
        },
        {
          "scientific_name": "Salvia officinalis",
          "common_name": "Sage",
          "why": "Handles dry conditions and low moisture with ease in partial shade.",
          "role_in_combination": "Adds velvety grey-green texture and mid-height mass that bridges the gap between tall shrubs and low succulents."
        }
      ],
      "maintenance": [
        "Water every 10 days during summer, monthly in winter",
        "Prune back woody stems by one-third in early spring to encourage bushy new growth",
        "Feed with a balanced slow-release fertiliser once in mid-spring"
      ]
    },
    {
      "zone_name": "Floor Level Edging",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "in wide shallow containers along the balcony floor edge in partial shade",
      "plants": [
        {
          "scientific_name": "Sansevieria trifasciata",
          "common_name": "Snake Plant",
          "why": "Tolerates low moisture and partial shade effortlessly.",
          "role_in_combination": "Provides striking vertical sword-like leaf accents at the base that contrast with the rounded rosettes and bushy herbs."
        },
        {
          "scientific_name": "Crassula argentea",
          "common_name": "Jade Plant",
          "why": "A drought-tolerant succulent suited to low moisture environments.",
          "role_in_combination": "Adds woody stems and fleshy green leaves, creating a miniature tree-like structure at the lower layer."
        }
      ],
      "maintenance": [
        "Water thoroughly only when soil is completely dry",
        "Wipe dust from the leaves with a damp cloth as needed",
        "Repot every 3 to 4 years when root-bound"
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers with a finger test before watering",
      "frequency": "every 10 to 14 days in summer, every 4 weeks in winter",
      "season": "all seasons"
    },
    {
      "task": "Prune back the Lemon Verbena and Sage to maintain compact form and encourage fresh shoots",
      "frequency": "once annually",
      "season": "early spring"
    },
    {
      "task": "Clear away any fallen debris from the surface of the pots to prevent fungal issues",
      "frequency": "monthly",
      "season": "autumn"
    }
  ],
  "care_cautions": [
    "Overwatering the Echeveria elegans and Crassula argentea in the cooler months can cause stem rot and leaf drop.",
    "The Aloysia triphylla may suffer from frost damage if left exposed during freezing winter conditions and should be moved to a protected spot."
  ],
  "pet_safety_note": "There are no pets in the household, ensuring that aromatic and succulent species can be grown safely without risk of ingestion."
}
